def obj(q,f):
    q=np.clip(q,-6,4)
    c3,c5=np.exp(q)
    A=np.column_stack([v**2,np.log(1+c3*x)*t,np.exp(-c5*t**2)*v,f])
    try:
        c=np.linalg.lstsq(A,y,rcond=None)[0]
